using TMPro;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// Plain reference holder for the Fight HUD PREFAB (Assets/_Project/Prefabs/UI/FightHud.prefab,
/// UIPrefabLibrarySO.fightHud, generated by Tools > MusicGame > UI > Build All UI Prefabs and edited by
/// hand from then on). FightController instantiates it once and only READS these references to drive
/// the timer/health/pips/portraits/pause/camera-toggle logic — it never creates or lays out UI itself.
/// </summary>
public class FightHudView : MonoBehaviour
{
    [Header("Root")]
    public GameObject root;

    [Header("Top bar")]
    public TextMeshProUGUI playerNameText;
    public Image       playerHealthFill;
    public TextMeshProUGUI playerRoundPipsText;
    public TextMeshProUGUI opponentNameText;
    public Image       opponentHealthFill;
    public TextMeshProUGUI opponentRoundPipsText;
    public TextMeshProUGUI timerText;
    public Button       pauseButton;
    public TextMeshProUGUI pauseButtonLabel;

    [Header("Portraits beside each fighter's name / health (the SAME sprites the VS screen shows)")]
    public Image playerPortrait;
    public Image opponentPortrait;
    [Tooltip("Face-centred crop of each portrait slot (crop parameters live on these components).")]
    public PortraitCrop playerPortraitCrop;
    public PortraitCrop opponentPortraitCrop;
    [Tooltip("Tint of a portrait slot with no sprite (no art yet) — same neutral placeholder as the VS screen.")]
    public Color portraitPlaceholderColor = new(1f, 1f, 1f, 0.2f);

    [Header("Camera view toggle (FightCameraController.ToggleView)")]
    public Button cameraToggleButton;
    public TextMeshProUGUI cameraToggleLabel;

    [Header("Pause menu")]
    public GameObject   pausePanel;
    public TextMeshProUGUI pauseTitleText;
    public Button       resumeButton;
    public TextMeshProUGUI resumeButtonLabel;
    public Button       mainMenuButton;
    public TextMeshProUGUI mainMenuButtonLabel;

    [Header("Mobile controls — visible ONLY during FightFlowState.Fighting, on real/simulated mobile")]
    public GameObject mobileControlsRoot;
    public RectTransform joystickBackground;
    public RectTransform joystickHandle;
    public VirtualJoystick joystick;
    public GameObject punchButton;
    public TouchActionButton punchAction;
    public TextMeshProUGUI punchButtonLabel;
    public GameObject kickButton;
    public TouchActionButton kickAction;
    public TextMeshProUGUI kickButtonLabel;
}
